function summarize(n, depth) {
  const o = { id: n.id, name: n.name, type: n.type, w: Math.round(n.width), h: Math.round(n.height) };
  if (n.type === 'TEXT') o.chars = n.characters, o.fontSize = n.fontSize, o.fontName = n.fontName;
  if ('fills' in n && Array.isArray(n.fills)) o.fills = n.fills.map(f => f.type + (f.color ? ':' + JSON.stringify(f.color) : ''));
  if ('cornerRadius' in n && typeof n.cornerRadius === 'number') o.r = n.cornerRadius;
  if ('strokes' in n && Array.isArray(n.strokes) && n.strokes.length) o.strokes = n.strokes.map(f => f.type);
  if (depth > 0 && 'children' in n) o.children = n.children.map(c => summarize(c, depth - 1));
  return o;
}

